function updateCamera(){orbit.phi=THREE.MathUtils.clamp(orbit.phi,.14,1.49);orbit.distance=THREE.MathUtils.clamp(orbit.distance,3,135);const s=Math.sin(orbit.phi);camera.position.set(orbit.target.x+orbit.distance*s*Math.sin(orbit.theta),orbit.target.y+orbit.distance*Math.cos(orbit.phi),orbit.target.z+orbit.distance*s*Math.cos(orbit.theta));camera.lookAt(orbit.target);}
