const pointers=new Map();const canvas=renderer.domElement;canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);activePointer=e.pointerId;lastPointer=[e.clientX,e.clientY];orbit.goal=null;if(pointers.size===2){const a=[...pointers.values()];pinch=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);}});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);if(pinch)orbit.distance*=pinch/d;pinch=d;return;}if(e.pointerId!==activePointer)return;const dx=e.clientX-lastPointer[0],dy=e.clientY-lastPointer[1];lastPointer=[e.clientX,e.clientY];if(e.buttons===2||e.shiftKey){const k=orbit.distance*.0017;orbit.target.x-=dx*k*Math.cos(orbit.theta);orbit.target.z+=dx*k*Math.sin(orbit.theta);orbit.target.y+=dy*k;}else{orbit.theta-=dx*.006;orbit.phi-=dy*.005;}});
