function secretScreen(){if(!parts?.secret||current!=='library')return null;const box=new THREE.Box3().setFromObject(parts.secret),point=box.getCenter(new THREE.Vector3());point.project(camera);return {x:(point.x+1)*innerWidth/2,y:(1-point.y)*innerHeight/2,visible:point.z>-1&&point.z<1&&Math.abs(point.x)<1&&Math.abs(point.y)<1};}
function pickSecret(x,y){if(!ready||current!=='library')return;const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(x/innerWidth*2-1,1-y/innerHeight*2),camera);const meshes=[];campus.traverseVisible(o=>{if(o.isMesh)meshes.push(o);});const hit=ray.intersectObjects(meshes,false)[0];let found=hit?.object;while(found&&found!==parts.secret)found=found.parent;if(found!==parts.secret)return;secretFound=true;$('secret-dialog').showModal();$('shelves').textContent='Explore shelves · ✓';}
function optimize(root){root.updateMatrixWorld(true);const boundary=root.getObjectByName('root')||root;const buckets=new Map();boundary.traverse(o=>{if(!o.isMesh)return;const mat=Array.isArray(o.material)?null:o.material;if(!mat)return;let branch=o;while(branch.parent&&branch.parent!==boundary)branch=branch.parent;const key=branch.name+'|'+mat.uuid;let bucket=buckets.get(key);if(!bucket)buckets.set(key,bucket={name:branch.name,mat,geometries:[]});const g=o.geometry.clone().applyMatrix4(o.matrixWorld);g.deleteAttribute('tangent');bucket.geometries.push(g);});const result=new THREE.Group();for(const b of buckets.values()){let geometry;try{geometry=mergeGeometries(b.geometries,false);}catch{}if(!geometry){for(const g of b.geometries){const m=new THREE.Mesh(g,b.mat);m.name=b.name;m.castShadow=true;m.receiveShadow=true;result.add(m);}continue;}const mesh=new THREE.Mesh(geometry,b.mat);mesh.name=b.name;mesh.castShadow=!b.mat.transparent;mesh.receiveShadow=true;result.add(mesh);for(const g of b.geometries)g.dispose();}return result;}
function put(id,pos=[0,0,0],rotation=0,parent=campus){const model=models.get(id).clone(true);model.position.set(...pos);model.rotation.y=rotation;model.userData.assetId=id;parent.add(model);placements.push({id,pos,rotation,model});return model;}
function instanceRepeated(parent){parent.updateMatrixWorld(true);const groups=new Map();for(const child of parent.children){const id=child.userData.assetId;if(!id)continue;if(!groups.has(id))groups.set(id,[]);groups.get(id).push(child);}for(const [id,copies] of groups){if(copies.length<2)continue;const group=new THREE.Group();group.name=`instances-${id}`;const inverse=new THREE.Matrix4().copy(parent.matrixWorld).invert();models.get(id).children.forEach((source,index)=>{if(!source.isMesh)return;const inst=new THREE.InstancedMesh(source.geometry,source.material,copies.length);inst.name=source.name;inst.castShadow=source.castShadow;inst.receiveShadow=true;copies.forEach((copy,i)=>{copy.updateMatrixWorld(true);inst.setMatrixAt(i,new THREE.Matrix4().multiplyMatrices(inverse,copy.matrixWorld));});inst.instanceMatrix.needsUpdate=true;inst.computeBoundingSphere();group.add(inst);});copies.forEach(copy=>parent.remove(copy));parent.add(group);}}
function setVisibility(){if(!parts)return;const assetMode=current==='assets';campus.visible=!assetMode;gallery.visible=assetMode;ground.visible=!assetMode;const cut=$('cutaway').checked,showRoofs=$('roofs').checked,floor=Number($('floor').value);parts.roof.visible=showRoofs&&(!cut||current==='terrace');parts.terrace.visible=parts.roof.visible;parts.levels.forEach((g,i)=>g.visible=!cut||i===floor);const libraryFrame=parts.levels[1].getObjectByName('instances-gh_timber_frame');if(libraryFrame)libraryFrame.visible=current!=='library';parts.warehouse.traverse(o=>{const m=o.name.match(/level_(\d+)_(front|back|sides)/);if(m)o.visible=!cut||(Number(m[1])===floor&&m[2]==='back');if(o.name==='structural_corner_pilasters')o.visible=!cut;});for(const shell of [parts.atrium,parts.bridge])shell.traverse(o=>{if(o.name==='roof')o.visible=showRoofs;if(shell===parts.atrium&&(o.name==='front'||o.name==='sides'))o.visible=current!=='atrium';});$('floor-label').hidden=!cut||assetMode;$('cut-label').hidden=assetMode;$('roof-label').hidden=assetMode;}
function pose(view,immediate=false){const phoneLibrary=innerWidth<700&&current==='library';orbit.goal={target:new THREE.Vector3(...view.target),distance:view.distance*(innerWidth<700?1.5:1),theta:phoneLibrary?0:view.theta,phi:phoneLibrary?1.47:view.phi};if(immediate){Object.assign(orbit,{distance:orbit.goal.distance,theta:orbit.goal.theta,phi:orbit.goal.phi});orbit.target.copy(orbit.goal.target);orbit.goal=null;updateCamera();}}
function showAsset(id){selected=id;gallery.children.slice(1).forEach(o=>gallery.remove(o));const m=models.get(id).clone(true);gallery.add(m);const box=new THREE.Box3().setFromObject(m),size=box.getSize(new THREE.Vector3());const center=box.getCenter(new THREE.Vector3());m.position.x-=center.x;m.position.z-=center.z;m.position.y-=box.min.y;const max=Math.max(size.x,size.y,size.z);pedestal.scale.set(Math.max(1,max/15),1,Math.max(1,max/15));const entry=kit.assets.find(a=>a.id===id);$('asset-select').value=id;$('asset-note').textContent=`${entry.name} · ${size.x.toFixed(1)} × ${size.y.toFixed(1)} × ${size.z.toFixed(1)} m. Drag to inspect every side.`;pose({...VIEWS.assets,target:[0,size.y*.45,0],distance:max*2.8});}
function setView(name,immediate=false){if(!ready||!VIEWS[name])return;current=name;const view=VIEWS[name];document.body.classList.toggle('asset-mode',name==='assets');document.body.classList.toggle('focus-view',!['campus','assets'].includes(name));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('kicker').textContent=view.kicker;$('view-title').textContent=view.title;$('view-note').textContent=name==='assets'?`Explore ${kit.assets.length} individual models for buildings, workspaces, murals and landscape.`:view.note;$('catalog').hidden=name!=='assets';$('shelves').hidden=name!=='library';$('cutaway').checked=['warehouse','library'].includes(name);$('roofs').checked=!['warehouse','library','atrium'].includes(name);if(name==='library')$('floor').value='1';if(name==='warehouse')$('floor').value='0';setVisibility();if(name==='assets')showAsset(selected);else pose(view,immediate);}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('cutaway').addEventListener('change',setVisibility);$('roofs').addEventListener('change',setVisibility);$('floor').addEventListener('change',()=>{const level=$('floor').value;if(current==='library'&&level!=='1'){setView('warehouse');$('floor').value=level;}setVisibility();if(current==='warehouse')pose({...VIEWS.warehouse,target:[-12,Number($('floor').value)*5+2,-5]});});$('reset').addEventListener('click',()=>current==='assets'?showAsset(selected):pose(current==='warehouse'&&$('cutaway').checked?{...VIEWS.warehouse,target:[-12,Number($('floor').value)*5+2,-5]}:VIEWS[current]));$('asset-select').addEventListener('change',e=>showAsset(e.target.value));$('about').addEventListener('click',()=>$('about-dialog').showModal());$('close-about').addEventListener('click',()=>$('about-dialog').close());
