function setNight(value){night=value;document.body.classList.toggle('night',value);$('light').textContent=value?'Daylight':'Dusk';$('light').setAttribute('aria-pressed',String(value));scene.background.set(value?'#25382d':'#e4ebe6');scene.fog.color.copy(scene.background);hemi.intensity=value?.75:2.25;sun.intensity=value?.8:3.2;fill.intensity=value?.65:.8;renderer.toneMappingExposure=value?1.4:1.25;}$('light').addEventListener('click',()=>setNight(!night));
async function load(){ready=false;$('loading').hidden=false;$('retry').hidden=true;try{kit=await fetch('/kit.json').then(r=>r.json());let loaded=0;const loader=new GLTFLoader();for(const a of kit.assets){if(!models.has(a.id)){const gltf=await loader.loadAsync(`/runtime/${a.id}.glb`);models.set(a.id,optimize(gltf.scene));}$('progress').textContent=`${++loaded} of ${kit.assets.length} models ready`;}parts=buildLayout(put,campus);for(const parent of [campus,...parts.levels,parts.terrace])instanceRepeated(parent);for(const a of kit.assets){const option=document.createElement('option');option.value=a.id;option.textContent=a.name;$('asset-select').append(option);}$('about-count').textContent=`All ${kit.assets.length}`;$('asset-count').textContent=`${kit.assets.length} models · ${placements.length} placements`;ready=true;$('loading').hidden=true;setView('campus',true);}catch(error){errors.push(error.message);$('progress').textContent='The campus kit is still being prepared. Retry when the exports are ready.';$('retry').hidden=false;}}
