function tick(now){frameMs=frameMs*.9+(now-last)*.1;last=now;if(orbit.goal){const g=orbit.goal;orbit.target.lerp(g.target,.1);orbit.distance=THREE.MathUtils.lerp(orbit.distance,g.distance,.1);orbit.theta=THREE.MathUtils.lerp(orbit.theta,g.theta,.1);orbit.phi=THREE.MathUtils.lerp(orbit.phi,g.phi,.1);if(Math.abs(orbit.distance-g.distance)<.005&&orbit.target.distanceTo(g.target)<.005)orbit.goal=null;}updateCamera();renderer.render(scene,camera);requestAnimationFrame(tick);}requestAnimationFrame(tick);
